const url = require('url');

function createResponse() {
  const res = {
    statusCode: 200,
    headers: {},
    body: null,
    status(code) {
      this.statusCode = code;
      return this;
    },
    setHeader(key, value) {
      this.headers[key] = value;
      return this;
    },
    json(data) {
      this.setHeader('Content-Type', 'application/json');
      this.body = data;
      return this;
    },
    send(data) {
      this.body = data;
      return this;
    },
    end() {
      return this;
    }
  };
  return res;
}

function parseQueryParams(urlString) {
  const parsed = url.parse(urlString, true);
  return parsed.query || {};
}

function matchRoutePattern(pattern, path) {
  const patternParts = pattern.split('/').filter(Boolean);
  const pathParts = path.split('/').filter(Boolean);

  if (patternParts.length !== pathParts.length) {
    return null;
  }

  const params = {};
  for (let i = 0; i < patternParts.length; i++) {
    const p = patternParts[i];
    const actual = pathParts[i];
    if (p.startsWith(':')) {
      const paramName = p.slice(1);
      params[paramName] = actual;
    } else if (p !== actual) {
      return null;
    }
  }
  return params;
}

class Router {
  constructor() {
    this.stack = [];
  }

  use(prefixOrFn, ...handlers) {
    let prefix = '/';
    let fns = [];
    if (typeof prefixOrFn === 'string') {
      prefix = prefixOrFn;
      fns = handlers;
    } else {
      fns = [prefixOrFn, ...handlers];
    }

    fns.forEach(fn => {
      this.stack.push({
        type: 'middleware',
        prefix,
        handler: fn
      });
    });
  }

  get(path, ...handlers) {
    this.addRoute('GET', path, handlers);
  }
  post(path, ...handlers) {
    this.addRoute('POST', path, handlers);
  }
  put(path, ...handlers) {
    this.addRoute('PUT', path, handlers);
  }
  delete(path, ...handlers) {
    this.addRoute('DELETE', path, handlers);
  }

  addRoute(method, path, handlers) {
    handlers.forEach(fn => {
      this.stack.push({
        type: 'route',
        method,
        path,
        handler: fn
      });
    });
  }

  async handle(req, res, mountPrefix = '') {
    const fullUrl = req.url || '/';
    const pathname = url.parse(fullUrl).pathname;
    req.query = parseQueryParams(fullUrl);

    for (const item of this.stack) {
      if (item.type === 'middleware') {
        const midPrefix = (mountPrefix + (item.prefix === '/' ? '' : item.prefix)).replace(/\/+/g, '/');
        if (pathname.startsWith(midPrefix)) {
          if (item.handler instanceof Router) {
            await item.handler.handle(req, res, midPrefix);
            if (res.body !== null) return res;
          } else if (typeof item.handler === 'function') {
            let nextCalled = false;
            await item.handler(req, res, () => { nextCalled = true; });
            if (!nextCalled && res.body !== null) return res;
          }
        }
      } else if (item.type === 'route') {
        if (req.method === item.method) {
          const routeFullPath = (mountPrefix + (item.path === '/' ? '' : item.path)).replace(/\/+/g, '/');
          const params = matchRoutePattern(routeFullPath, pathname);
          if (params) {
            req.params = params;
            await item.handler(req, res, () => {});
            return res;
          }
        }
      }
    }

    if (res.body === null && mountPrefix === '') {
      res.status(404).json({ error: 'Route not found' });
    }
    return res;
  }
}

function express() {
  const app = new Router();
  app.handleRequest = async function(req, res) {
    if (!res) res = createResponse();
    if (!req.query) req.query = parseQueryParams(req.url || '/');
    if (!req.params) req.params = {};
    return await app.handle(req, res, '');
  };
  return app;
}

express.Router = function() {
  return new Router();
};

express.json = function() {
  return function(req, res, next) {
    if (typeof req.body === 'string') {
      try {
        req.body = JSON.parse(req.body);
      } catch (e) {}
    }
    if (next) next();
  };
};

express.urlencoded = function() {
  return function(req, res, next) {
    if (next) next();
  };
};

module.exports = express;
